        if (st == NULL)
                return FALSE;

        /* hdrver */
        priv->hdrver = fu_struct_uswid_get_hdrver(st);
        if (priv->hdrver < FU_USWID_FIRMARE_MINIMUM_HDRVER) {
                g_set_error_literal(error,
                                    FWUPD_ERROR,
                                    FWUPD_ERROR_NOT_SUPPORTED,
                                    "header version was unsupported");
                return FALSE;
        }

